// Word of the day: a real word worth knowing, its sound, meaning and origin
// and a sentence using it, with an illustration of it. It remembers the last
// sixty words so as not to come back to them. Needs an OpenAI API key.
import { apiKey, askJson, paint, pictureFor, readRecord, sizeFor, dayKey } from './ai'

const KINDS: Record<string, string> = {
  delightful: 'a delightful, little-known word with a story behind it',
  useful: 'an uncommon but useful word that would make everyday speech more precise',
  untranslatable: 'a word from another language with no single English equivalent',
  old: 'a lovely old English word that has fallen out of use',
}

const SYSTEM = `You choose a word of the day for a picture frame on someone's wall. The word must be real and
its meaning and origin accurate. Answer JSON only:
{"word": "the word", "pronunciation": "a plain respelling with the stressed syllable in capitals, like ah-PRISS-ih-tee", "partOfSpeech": "noun, verb, ...",
"language": "the language it is from, if not English, else empty",
"definition": "a clear definition, at most 25 words", "origin": "where it comes from, at most 25 words",
"example": "a natural sentence using it, at most 22 words",
"illustration": "a prompt for a charming illustration of the word's meaning, 30 to 60 words, no text"}`

export function get(app: FrameOSApp, context: FrameOSContext) {
  return pictureFor(app, 'word', dayKey(new Date()), 'ai-scenes/word-of-the-day', (path) => {
    const key = apiKey()
    const before = readRecord(app.state.word)
    const recent: string[] = before && before.text && Array.isArray(before.text.recent) ? before.text.recent : []
    const kind = KINDS[String(app.config.kind)] || KINDS.delightful
    const chosen = askJson(
      key,
      String(app.config.textModel || 'gpt-6.1-terra'),
      SYSTEM,
      `Choose ${kind}.${recent.length ? ` Not one of these, used lately: ${recent.join(', ')}.` : ''}`,
    )
    const width = context.targetWidth || context.imageWidth || app.frame.width
    const height = context.targetHeight || context.imageHeight || app.frame.height
    const model = String(app.config.imageModel || 'gpt-image-2')
    paint(key, model, `${chosen.illustration}\n\nA warm, witty editorial illustration with a little texture. No text or letters.`, sizeFor(model, width, height, app.frame.embedded), path, app.frame.embedded)
    const word = String(chosen.word || '')
    return {
      word,
      pronunciation: String(chosen.pronunciation || ''),
      partOfSpeech: String(chosen.partOfSpeech || ''),
      language: String(chosen.language || ''),
      definition: String(chosen.definition || ''),
      origin: String(chosen.origin || ''),
      example: String(chosen.example || ''),
      recent: [word].concat(recent).slice(0, 60),
    }
  })
}

