import { readRecord } from './record'
export { readRecord, pad, dayKey, WEEKDAYS, MONTHS } from './record'

// What the AI scenes share: OpenAI's text and image calls, and the record of
// the latest picture, kept in the scene's state so a restart shows it again
// rather than paying for another. The picture is written straight from the
// reply into the scene's own folder (httpRequest's saveBase64Field): it never
// becomes a JS string, which on an ESP32 would not fit.

export type Record = {
  key: string // which period it is for: a day, or a day and an hour
  path: string // the picture, in the scene's own folder
  text: any // what the scene says beside it
  error?: string
  triedAt?: number
}

// After a failed attempt, wait this long before paying for another.
const RETRY_MS = 30 * 60000

// What a frame without the key says. Settings is where the key goes on
// every plane (a frame with no plane has Settings of its own).
const NO_KEY = 'Add an OpenAI API key in Settings.'

export function apiKey() {
  const key = frameos.getSetting('openAI', 'apiKey')
  if (!key) throw new Error(NO_KEY)
  return key
}

function failure(r: any) {
  if (!r.status) return r.error || 'no answer from OpenAI'
  try {
    const json = JSON.parse(r.body)
    return (json.error && json.error.message) || `OpenAI said ${r.status}`
  } catch (e) {
    return `OpenAI said ${r.status}`
  }
}

// One chat turn that answers a JSON object.
export function askJson(key: string, model: string, system: string, user: string) {
  const r = frameos.httpRequest('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: user },
      ],
    }),
    timeoutMs: 120000,
  })
  if (r.status !== 200) throw new Error(failure(r))
  const content = JSON.parse(r.body).choices[0].message.content
  return JSON.parse(content)
}

// The image size for the box the picture fills: wide, tall or square. An
// ESP32 asks for the smaller sizes, at low quality, as JPEG.
export function sizeFor(model: string, width: number, height: number, embedded: boolean) {
  const ratio = width / Math.max(1, height)
  const small = embedded && model === 'gpt-image-2'
  if (ratio > 1.2) return small ? '1024x640' : '1536x1024'
  if (ratio < 0.83) return small ? '640x1024' : '1024x1536'
  return '1024x1024'
}

// Paints the prompt into path. Throws with OpenAI's reason if it cannot.
export function paint(key: string, model: string, prompt: string, size: string, path: string, embedded: boolean) {
  const r = frameos.httpRequest('https://api.openai.com/v1/images/generations', {
    method: 'POST',
    headers: { Authorization: `Bearer ${key}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model, prompt, size, n: 1, quality: embedded ? 'low' : 'medium', output_format: 'jpeg', output_compression: 82 }),
    timeoutMs: 300000,
    saveBase64Field: { field: 'b64_json', path },
  })
  if (r.status !== 200) throw new Error(failure(r))
  if (r.saveError) throw new Error(`could not keep the picture: ${r.saveError}`)
  if (!r.saved) {
    // A runtime that does not save fields hands the picture over inline.
    const b64 = JSON.parse(r.body).data[0].b64_json
    if (!b64 || !frameos.writeAsset(path, b64)) throw new Error('could not keep the picture')
  }
}

// The picture for this period: the one already made, or a new one from
// make(), which paints into the path it is given and returns the words.
// The record goes into the scene's state under stateKey.
export function pictureFor(app: FrameOSApp, stateKey: string, key: string, folder: string, make: (path: string) => any) {
  const record = readRecord(app.state[stateKey])
  if (record && record.key === key && record.path && !record.error) {
    const image = frameos.loadAssetImage(record.path)
    if (image) return image
  }
  if (record && record.key === key && record.error && record.triedAt && Date.now() - record.triedAt < RETRY_MS) {
    throw new Error(record.error)
  }
  const path = `${folder}/${key.replace(/[^0-9A-Za-z-]/g, '-')}.jpg`
  try {
    const text = make(path)
    const fresh: Record = { key, path, text }
    if (record && record.path && record.path !== path) frameos.deleteAsset(record.path)
    frameos.setState(stateKey, fresh)
    const image = frameos.loadAssetImage(path)
    if (!image) throw new Error('the picture did not load')
    return image
  } catch (e) {
    const message = e && e.message ? e.message : String(e)
    // A missing key is no attempt: once it is added, the next render paints.
    const missingKey = message === NO_KEY
    const failed: Record = { ...(record || { path: '', text: null }), key, error: message, triedAt: missingKey ? undefined : Date.now() }
    frameos.setState(stateKey, failed)
    throw e
  }
}

