// The dictionary entry beside the illustration: the word large, how to say
// it, what it means, where it comes from, and the word in a sentence.
import { readRecord } from './record'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const W = context.imageWidth ?? app.frame.width
  const H = context.imageHeight ?? app.frame.height
  const record = readRecord(app.state.word)
  const text = record && record.text
  const u = Math.min(W, H) / 100
  const pad = Math.round(u * 6)

  const round = roundColumn(app, W, H)
  if (round && !text) {
    // On a round panel, the note poured into the circle's right-hand part.
    const R = round.r
    const lines = flowIntoCircleCentred(
      [
        { text: 'Word of the day', className: `font-[Cormorant_Garamond] font-bold text-[${Math.round(R * 0.11)}px] leading-[${Math.round(R * 0.13)}px] text-[#1e2a3a]`, lead: Math.round(R * 0.13), gap: Math.round(R * 0.04) },
        { text: record && record.error ? String(record.error) : 'A new word every morning. Add an OpenAI API key in Settings.', className: 'font-[FiraGO] text-[15px] leading-[20px] text-[#6b7480]', lead: 20, gap: 0 },
      ],
      Math.round(R * 0.2),
      H - Math.round(R * 0.14),
      round,
      Math.round(R * 0.07),
    )
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-[#fdfbf6]`}>
        {lines.map((line) => (
          <div className={`absolute top-[${line.y}px] left-[${line.left}px] w-[${line.width}px] whitespace-nowrap ${line.className}`}>{line.text}</div>
        ))}
      </div>
    )
  }

  if (!text) {
    return (
      <div className={`flex flex-col w-full h-full bg-[#fdfbf6] p-[${pad}px] justify-center`}>
        <div className={`font-[Cormorant_Garamond] font-bold text-[${Math.round(u * 8)}px] text-[#1e2a3a]`}>Word of the day</div>
        <div className={`font-[FiraGO] text-[${Math.round(u * 3.6)}px] text-[#6b7480] mt-[${Math.round(u * 2)}px]`}>
          {record && record.error ? record.error : 'A new word every morning. Add an OpenAI API key in Settings.'}
        </div>
      </div>
    )
  }
  if (round) {
    // On a round panel: the entry poured into the circle's right-hand part,
    // its lines running out to the rim.
    const R = round.r
    const size = Math.max(14, Math.round(R * 0.066))
    const lead = Math.round(size * 1.3)
    const labelClass = 'font-[FiraGO] uppercase text-[14px] leading-[18px] text-[#b4552d]'
    const bodyClass = `font-[FiraGO] text-[${size}px] leading-[${lead}px] text-[#26313f]`
    const big = Math.round(Math.min(R * 0.2, (W * 0.8) / Math.max(4, text.word.length * 0.5)))
    const lines = flowIntoCircleCentred(
      [
        { text: 'Word of the day', className: 'font-[FiraGO] uppercase text-[14px] leading-[18px] text-[#8a929c]', lead: 18, gap: 2 },
        { text: String(text.word), className: `font-[Cormorant_Garamond] font-bold text-[${big}px] leading-[${Math.round(big * 1.05)}px] text-[#1e2a3a]`, lead: Math.round(big * 1.05), gap: 2, lines: 1 },
        { text: [text.pronunciation, text.partOfSpeech].filter(Boolean).join(' · '), className: `font-[FiraGO] text-[14px] leading-[18px] text-[#6b7480]`, lead: 18, gap: Math.round(R * 0.04), lines: 1 },
        { text: 'Meaning', className: labelClass, lead: 18, gap: 2 },
        { text: String(text.definition), className: bodyClass, lead, gap: Math.round(R * 0.04), lines: 4 },
        { text: `“${text.example}”`, className: `font-[Cormorant_Garamond] font-bold text-[${size}px] leading-[${lead}px] text-[#26313f]`, lead, gap: 0 },
      ],
      Math.round(R * 0.22),
      H - Math.round(R * 0.14),
      round,
      Math.round(R * 0.07),
    )
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-[#fdfbf6]`}>
        {lines.map((line) => (
          <div className={`absolute top-[${line.y}px] left-[${line.left}px] w-[${line.width}px] whitespace-nowrap ${line.className}`}>{line.text}</div>
        ))}
      </div>
    )
  }

  // The word as big as its column lets it be.
  const wordSize = Math.round(Math.min(u * 13, (W - pad * 2) / Math.max(4, text.word.length * 0.5)))
  const label = `font-[FiraGO] uppercase text-[${Math.round(u * 2.5)}px] text-[#b4552d] mt-[${Math.round(u * 2.6)}px]`
  const body = `font-[FiraGO] text-[${Math.round(u * 3.6)}px] leading-snug text-[#26313f]`
  return (
    <div className={`flex flex-col w-full h-full bg-[#fdfbf6] px-[${pad}px] py-[${Math.round(pad * 0.8)}px]`}>
      <div className={`font-[FiraGO] uppercase text-[${Math.round(u * 2.6)}px] text-[#8a929c]`}>Word of the day</div>
      <div className={`font-[Cormorant_Garamond] font-bold text-[${wordSize}px] leading-none text-[#1e2a3a] mt-[${Math.round(u * 1.4)}px]`}>{text.word}</div>
      <div className={`font-[FiraGO] text-[${Math.round(u * 3.2)}px] text-[#6b7480] mt-[${Math.round(u * 1.2)}px]`}>
        {[text.pronunciation, text.partOfSpeech, text.language].filter(Boolean).join(' · ')}
      </div>
      <div className="flex flex-col flex-1 min-h-0 overflow-hidden">
        <div className={label}>Meaning</div>
        <div className={body}>{text.definition}</div>
        <div className={label}>Origin</div>
        <div className={body}>{text.origin}</div>
        <div className={`border-l-[3px] border-[#b4552d] pl-[${Math.round(u * 2)}px] mt-[${Math.round(u * 3)}px] font-[Cormorant_Garamond] font-bold text-[${Math.round(u * 4.2)}px] leading-snug text-[#26313f]`}>
          {`“${text.example}”`}
        </div>
      </div>
    </div>
  )
}

// On a round panel only the circle inside the square shows, and the scene's
// split puts this page in its right-hand column: the panel's full height, up
// to its right edge. Where the circle is in the page's own pixels, or null on
// every other panel and in any other room.
function roundColumn(app: FrameOSApp, W: number, H: number) {
  const side = Math.min(app.frame.width, app.frame.height)
  if (app.frame.round !== true || Math.abs(H - side) > 1 || W >= side - 1) return null
  return { cx: W - side / 2, cy: H / 2, r: side / 2 }
}

type Flowed = { text: string; className: string; y: number; left: number; width: number }

// The same, moved down to the middle of the room when it leaves room below.
function flowIntoCircleCentred(
  blocks: { text: string; className: string; lead: number; gap: number; lines?: number }[],
  top: number,
  bottom: number,
  at: { cx: number; cy: number; r: number },
  seam: number,
) {
  const first = flowIntoCircle(blocks, top, bottom, at, seam)
  const last = first[first.length - 1]
  const slack = last ? bottom - (last.y + blocks[blocks.length - 1].lead) : 0
  if (slack < 20) return first
  const lower = flowIntoCircle(blocks, top + Math.round(slack / 2), bottom, at, seam)
  const said = (lines: Flowed[]) => lines.map((line) => line.text).join(' ')
  return said(lower) === said(first) ? lower : first
}

// Blocks of text poured into the circle from `top` to `bottom`: each line
// from the page's left edge (`seam` in) to the rim (12 px in), measured so
// nothing is cut. A block stops at its `lines`, the text at `bottom`, and
// what does not fit ends in "…".
function flowIntoCircle(
  blocks: { text: string; className: string; lead: number; gap: number; lines?: number }[],
  top: number,
  bottom: number,
  at: { cx: number; cy: number; r: number },
  seam: number,
) {
  const out: Flowed[] = []
  let y = top
  const shorten = (line: Flowed | undefined) => {
    if (line) line.text = line.text.includes(' ') ? line.text.replace(/\s+\S+$/, '…') : line.text + '…'
  }
  for (const block of blocks) {
    let used = 0
    const paragraphs = block.text.split(/\n\s*\n/).map((p) => p.trim()).filter(Boolean)
    for (let p = 0; p < paragraphs.length; p++) {
      const words = paragraphs[p].split(/\s+/)
      let k = 0
      while (k < words.length) {
        if (y + block.lead > bottom || (block.lines && used >= block.lines)) {
          shorten(used ? out[out.length - 1] : undefined)
          if (y + block.lead > bottom) return out
          p = paragraphs.length
          break
        }
        const dy = Math.max(Math.abs(y - at.cy), Math.abs(y + block.lead - at.cy))
        const half = Math.sqrt(Math.max(0, at.r * at.r - dy * dy))
        const left = Math.max(0, at.cx - half) + seam
        const width = Math.floor(at.cx + half - 12 - left)
        if (width < block.lead * 3) {
          y += block.lead
          continue
        }
        const tries = []
        for (let n = 1; n <= Math.min(words.length - k, 24); n++) tries.push(words.slice(k, k + n).join(' '))
        const heights = frameos.measureText(tries, { className: block.className, width })
        let n = 1
        while (n < tries.length && heights[n] <= heights[0]) n++
        out.push({ text: tries[n - 1], className: block.className, y, left: Math.round(left), width })
        k += n
        used++
        y += block.lead
      }
      if (p < paragraphs.length - 1) y += Math.round(block.lead * 0.35)
    }
    y += block.gap
  }
  return out
}

